def _enable_row_level_security() -> None:
    """Postgres only. A session sees a row only when app.tenant_id matches it, or is '*' for system work
    (the queue worker, verified payer webhooks). Unset sees nothing, so a forgotten filter fails closed.
    FORCE applies the policy to the table owner too, which is the account the app connects as."""
    if op.get_bind().dialect.name != "postgresql":
        return
    for table in TENANT_TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(
            f"CREATE POLICY tenant_isolation ON {table} "
            "USING (current_setting('app.tenant_id', true) IN (tenant_id, '*')) "
            "WITH CHECK (current_setting('app.tenant_id', true) IN (tenant_id, '*'))"
        )


def _disable_row_level_security() -> None:
    if op.get_bind().dialect.name != "postgresql":
        return
    for table in TENANT_TABLES:
        op.execute(f"DROP POLICY IF EXISTS tenant_isolation ON {table}")
        op.execute(f"ALTER TABLE {table} DISABLE ROW LEVEL SECURITY")
